"""Inline, dependency-free dashboard markup for the optional multi-AI review."""


def dashboard_html() -> str:
    return """<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Multi-AI Crochet Review</title>
<style>
:root{color-scheme:light;--ink:#19313b;--muted:#526870;--line:#d7e1e2;--paper:#f5f8f7;--teal:#176b62;--cream:#fffdf8;--red:#9a332a;--gold:#775409}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.55 system-ui,-apple-system,"Segoe UI",sans-serif}.wrap{max-width:1180px;margin:auto;padding:26px 18px 60px}h1,h2,h3{line-height:1.2}header{padding:20px 0 14px}header h1{font-size:clamp(1.8rem,4vw,2.6rem);margin:.1em 0;color:#174e49}header p{max-width:850px;color:var(--muted)}.notice{padding:14px 16px;background:#fff4d6;border:1px solid #e7d497;border-radius:9px;margin:16px 0}.grid{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(280px,.75fr);gap:18px}.panel{background:var(--cream);border:1px solid var(--line);border-radius:12px;padding:18px;box-shadow:0 3px 14px #1739360b}.panel h2{font-size:1.25rem;margin:0 0 12px}.wide{grid-column:1/-1}label{display:block;font-weight:650;margin:.5rem 0 .35rem}textarea,input{font:inherit;width:100%;border:1px solid #afc0c2;border-radius:8px;padding:11px;background:#fff;color:var(--ink)}textarea{min-height:270px;resize:vertical;font:14px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace}.smallarea{min-height:80px}.btn{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:8px;background:var(--teal);color:white;padding:10px 16px;font:inherit;font-weight:700;cursor:pointer;margin:10px 7px 0 0}.btn.secondary{background:#e5efed;color:#174e49;border:1px solid #bdcfcb}.btn:disabled{opacity:.55;cursor:wait}.muted{color:var(--muted);font-size:.92rem}.status{font-weight:750;padding:10px 12px;border-radius:8px;background:#edf2f2;margin:10px 0}.status.good{color:#155c3a;background:#e6f5ec}.status.bad{color:var(--red);background:#fbe9e6}.provider{border-top:1px solid var(--line);padding:9px 0}.provider strong{display:block}.history-item{border-bottom:1px solid var(--line);padding:9px 0}.history-item button{background:none;border:0;color:#155c5a;text-decoration:underline;font:inherit;text-align:left;cursor:pointer;padding:0}.report{white-space:pre-wrap;overflow-wrap:anywhere;max-height:900px;overflow:auto;background:#12242a;color:#e8f4ef;padding:14px;border-radius:8px;font:12px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace}.proposal{border:1px solid var(--line);padding:12px;border-radius:8px;margin:10px 0}.proposal p{margin:.35rem 0}.row{display:grid;grid-template-columns:1fr 1fr;gap:12px}#progress{min-height:1.5em;color:var(--muted)}.draftdiff{white-space:pre-wrap;overflow-wrap:anywhere;background:#eef3f2;border-radius:7px;padding:12px;font:13px/1.5 ui-monospace,monospace}footer{padding:22px 0;color:var(--muted);font-size:.9rem}@media(max-width:800px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}.row{grid-template-columns:1fr}}
</style></head><body><main class="wrap">
<header><h1>Multi-AI Crochet Pattern Review</h1><p>Optional, server-side provider reviews layered onto the existing deterministic written-text checker. Provider calls are real only when configured and successful; failures and missing participation are reported rather than represented as reviews.</p></header>
<div class="notice"><strong>Scope:</strong> This checks written text, not a crocheted sample. It does not verify gauge, fit, fabric, durability, safety, or finishing in the physical world. A proposed correction is a separate draft and must complete validation again; the submitted original is preserved.</div>
<div class="grid">
<section class="panel"><h2>Submit a pattern</h2><label for="pattern">Pattern text</label><textarea id="pattern" maxlength="100000" placeholder="Paste written pattern instructions here"></textarea><button class="btn" id="run">Run deterministic and configured AI checks</button><p id="progress" aria-live="polite">Provider credentials remain on the server. No model is called until you submit.</p><div id="runstatus" class="status" hidden></div></section>
<section class="panel"><h2>Provider configuration</h2><p class="muted">Readiness below is based only on local environment settings. It does not probe whether a service, model, quota, or credential works.</p><div id="providers" class="muted">Loading status…</div><h3>Review policy</h3><div id="settings" class="muted"></div></section>
<section class="panel"><h2>Recent runs</h2><button class="btn secondary" id="refresh">Refresh history</button><div id="history" class="muted">Loading…</div></section>
<section class="panel"><h2>Separate correction draft</h2><p class="muted">Choose an exact source excerpt, replacement text, and reason. The original is never changed. The draft is queued for a full fresh validation.</p><div id="draftSource" class="muted">Load a completed report with a correction proposal to prepare a draft, or fill in the exact text manually.</div><label for="from">Exact text to replace (must occur once)</label><textarea class="smallarea" id="from" maxlength="5000"></textarea><label for="to">Replacement text</label><textarea class="smallarea" id="to" maxlength="5000"></textarea><label for="reason">Reason for the proposed change</label><textarea class="smallarea" id="reason" maxlength="2000"></textarea><button class="btn" id="draft" disabled>Create and revalidate separate draft</button><div id="draftresult"></div></section>
<section class="panel wide"><h2>Detailed report</h2><p class="muted">The complete API report is shown verbatim, including deterministic checks, reviewer phases, evidence grounding, disagreements, participation, failures, cost/latency, written construction gaps, and the fail-closed gate.</p><pre id="report" class="report">No run selected.</pre></section>
</div><footer>Local history is stored in the configured SQLite database. Protect the host and database if patterns are private. Never expose provider keys in browser code.</footer>
</main><script>
const $=id=>document.getElementById(id);let selectedRun=null;let polling=false;
function showStatus(message,good){const box=$('runstatus');box.hidden=false;box.textContent=message;box.className='status '+(good?'good':'bad')}
async function api(url,options={}){const response=await fetch(url,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});let data;try{data=await response.json()}catch{data={detail:'Response was not valid JSON'}}if(!response.ok)throw new Error(data.detail||('HTTP '+response.status));return data}
function setRun(report){selectedRun=report.run_id||selectedRun;$('report').textContent=JSON.stringify(report,null,2);$('draft').disabled=!selectedRun||['failed','failed_to_persist_completed_report'].includes(report.execution_status);$('draftSource').textContent=selectedRun?'Draft parent run: '+selectedRun+' — original pattern remains unchanged.':'No completed parent run selected.';renderProposals(report.correction_proposals||[]);const gate=report.gate||{};const consensus=(report.ai_consensus||{}).status||'not evaluated';showStatus((gate.status||report.approval_status||report.status||'Report')+' — AI consensus: '+consensus+(gate.blocker_count?' — '+gate.blocker_count+' gate blocker(s)':''),!!gate.approved)}
function renderProposals(items){const host=$('draftSource');if(!items.length)return;const list=document.createElement('div');const title=document.createElement('p');title.textContent='Correction proposals (not applied):';list.appendChild(title);for(const item of items){const card=document.createElement('div');card.className='proposal';const text=document.createElement('p');text.textContent=(item.original_excerpt||'')+' → '+(item.proposed_correction_snippet||'')+' — '+(item.reason||'');card.appendChild(text);const button=document.createElement('button');button.className='btn secondary';button.type='button';button.textContent='Prepare this proposal as a separate draft';button.addEventListener('click',()=>{$('from').value=item.original_excerpt||'';$('to').value=item.proposed_correction_snippet||'';$('reason').value=item.reason||'Review proposed correction';$('draft').disabled=!selectedRun;$('from').focus()});card.appendChild(button);list.appendChild(card)}host.appendChild(list)}
async function loadProviders(){try{const data=await api('/api/consensus/providers');const status=data.status||{};$('providers').textContent='Selected: '+((status.selected_provider_ids||[]).join(', ')||'none')+' | Required: '+((status.required_provider_ids||[]).join(', ')||'none')+' | Configuration issues: '+((status.configuration_issues||[]).join('; ')||'none');for(const p of status.providers||[]){const row=document.createElement('div');row.className='provider';const name=document.createElement('strong');name.textContent=p.provider_id+' — '+(p.selected?'selected':'not selected')+' — '+(p.ready?'locally configured':'not ready');row.appendChild(name);const detail=document.createElement('span');detail.textContent='Model: '+(p.model||'not configured')+'; Role: '+(p.role||'automatic specialist assignment')+'; '+(p.readiness_scope||'')+(p.missing_configuration&&p.missing_configuration.length?' Missing: '+p.missing_configuration.join(', '):'');row.appendChild(detail);$('providers').appendChild(row)}$('settings').textContent='Minimum independent participants: '+data.settings.min_participating_models+'; minimum participation ratio: '+data.settings.min_participation_ratio+'; issue support threshold: '+data.settings.consensus_threshold+'; maximum concurrent calls: '+data.settings.max_concurrency+'; strict required participation: '+data.settings.strict_required_participation+'; cross-examination: '+data.settings.cross_examination_enabled+'; adversarial review: '+data.settings.adversarial_review_enabled+'; required roles: '+data.settings.required_roles.join(', ')+'; max draft revisions: '+data.settings.max_revisions}catch(error){$('providers').textContent='Could not load status: '+error.message}}
async function loadHistory(){try{const data=await api('/api/consensus/runs?limit=50');const host=$('history');host.textContent='';if(!data.runs.length){host.textContent='No saved runs yet.';return}for(const run of data.runs){const row=document.createElement('div');row.className='history-item';const button=document.createElement('button');button.textContent=run.created_at+' — '+run.status+' — '+(run.approval_status||'not yet reported')+' — '+(run.participating_model_count||0)+' confirmed, '+(run.failed_model_count||0)+' failed, '+(run.unknown_model_count||0)+' unknown — '+run.run_id;button.addEventListener('click',()=>loadRun(run.run_id));row.appendChild(button);host.appendChild(row)}}catch(error){$('history').textContent='Could not load history: '+error.message}}
async function loadRun(id){try{const run=await api('/api/consensus/runs/'+encodeURIComponent(id));selectedRun=run.run_id;if(run.report){setRun(run.report)}else{$('report').textContent=JSON.stringify(run,null,2);showStatus('Run status: '+run.status,false)}}catch(error){showStatus(error.message,false)}}
async function waitForRun(id){polling=true;for(let i=0;i<600;i++){const run=await api('/api/consensus/runs/'+encodeURIComponent(id));if(run.report){setRun(run.report);await loadHistory();polling=false;return}if(run.status==='failed'){showStatus('Run failed closed: '+(run.error||'No approval issued'),false);$('report').textContent=JSON.stringify(run,null,2);await loadHistory();polling=false;return}$('progress').textContent=(run.progress&&run.progress.message)||('Run status: '+run.status);await new Promise(resolve=>setTimeout(resolve,1000))}polling=false;showStatus('Polling timed out. Run remains in history; refresh or reopen it.',false)}
$('run').addEventListener('click',async()=>{if(polling)return;const text=$('pattern').value;if(!text.trim()){showStatus('Enter written pattern text first.',false);return}$('run').disabled=true;$('progress').textContent='Queued. Waiting for deterministic and provider checks…';try{const run=await api('/api/consensus/runs',{method:'POST',body:JSON.stringify({pattern_text:text})});selectedRun=run.run_id;await loadHistory();await waitForRun(run.run_id)}catch(error){polling=false;showStatus(error.message,false)}finally{$('run').disabled=false}});
$('draft').addEventListener('click',async()=>{if(!selectedRun)return;const changes=[{from_text:$('from').value,to_text:$('to').value,reason:$('reason').value}];const out=$('draftresult');out.textContent='';try{const result=await api('/api/consensus/runs/'+encodeURIComponent(selectedRun)+'/drafts',{method:'POST',body:JSON.stringify({changes})});const title=document.createElement('p');title.textContent='Separate draft queued: '+result.draft.run_id+' (revision '+result.draft.revision_number+'). Parent remains '+result.draft.parent_run_id+'.';out.appendChild(title);const diff=document.createElement('pre');diff.className='draftdiff';diff.textContent=result.draft.diff||'(No diff text)';out.appendChild(diff);selectedRun=result.draft.run_id;$('draft').disabled=true;await loadHistory();await waitForRun(selectedRun)}catch(error){polling=false;out.textContent='Draft not created: '+error.message}});
$('refresh').addEventListener('click',loadHistory);loadProviders();loadHistory();
</script></body></html>"""
